WITH base AS (SELECT *, HOUR(started_at) AS started_at_hour, COALESCE(country, 'DIRECT') AS resolved_country FROM sessions WHERE started_at >= TIMESTAMP '2023-08-16 16:00:00' AND customer_id IS NOT NULL) SELECT id, started_at, country, started_at_hour, resolved_country FROM base QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY started_at_hour DESC NULLS FIRST, id) = 1;
